10:   const segments = useSegments();
11:   const { isHydrated, accessToken } = useAuthStore();
12:   useEffect(() => {
13:     if (!isHydrated) return;
14:     const inAuth = segments[0] === '(auth)';
15:     if (!accessToken && !inAuth) router.replace('/(auth)/login');
16:     if (accessToken && inAuth) router.replace('/(tabs)');
17:   }, [accessToken, isHydrated, router, segments]);
18:   return null;
19: }
